import itertools

def solve(n):
    subsets = []
    for i in range(1 << n):
        subset = []
        for j in range(n):
            if (i >> j) & 1:
                subset.append(j)
        subsets.append(frozenset(subset))

    num_subsets = len(subsets)
    count = 0

    # Iterate through all colorings (2^num_subsets)
    for coloring in itertools.product([0, 1], repeat=num_subsets):
        # coloring[i] is 1 if subset i is blue, 0 otherwise
        c = {subsets[i]: coloring[i] for i in range(num_subsets)}

        # Precompute f(T)
        f = {}
        for T in subsets:
            f[T] = sum(c[X] for X in subsets if X.issubset(T))

        # Check condition: f(T1)f(T2) = f(T1 U T2)f(T1 n T2)
        valid = True
        for T1 in subsets:
            for T2 in subsets:
                if f[T1] * f[T2] != f[T1 | T2] * f[T1 & T2]:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            count += 1
    return count

for n in range(1, 4):
    print(f"n={n}: {solve(n)}")

