import itertools

def get_valid_colorings(n):
    subsets = []
    for i in range(1 << n):
        subset = []
        for j in range(n):
            if (i >> j) & 1:
                subset.append(j)
        subsets.append(frozenset(subset))

    num_subsets = len(subsets)
    valid_colorings = []

    for coloring in itertools.product([0, 1], repeat=num_subsets):
        c = {subsets[i]: coloring[i] for i in range(num_subsets)}
        f = {T: sum(c[X] for X in subsets if X.issubset(T)) for T in subsets}

        valid = True
        for T1 in subsets:
            for T2 in subsets:
                if f[T1] * f[T2] != f[T1 | T2] * f[T1 & T2]:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            valid_colorings.append(c)
    return valid_colorings

